//! 📨️ A deferred response captures the actual cached view and admitted actor once under its original continuation.
use super::*;
use semio_framework_job::{OriginalConstructionAdmission,OriginalSourceBinding,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetirementDemand,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use semio_plugin_plugin_program::surface_context::OriginalSurfaceViewCapture;
use semio_framework_value::retained_clone::NativeAllocationIdentity;
use semio_plugin_decl_emission::ViewLease;
use semio_plugin_job_receiving::original_steps::{construction,receipt};
use std::mem::{ManuallyDrop,size_of};
use crate::{adopted,begun,built,built_with,retired,retired_poll,unbuilt};
/// 🧷️ Every retry borrows this same source; cancellation restores the cache before its caller returns.
pub struct OriginalResponseActionSource{instance:u32,binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),body:usize,surface:Option<(usize,usize)>,capture:ManuallyDrop<Option<Box<OriginalSurfaceViewCapture>>>,owned_view:ManuallyDrop<Option<semio_framework::ViewModel>>,view:ManuallyDrop<Option<std::sync::Arc<semio_framework::ViewModel>>>,lease:ManuallyDrop<Option<ViewLease>>,allocation:semio_framework_value::native_decoding::NativeSharedAdmission<semio_framework::ViewModel>,actor:ManuallyDrop<Option<String>>,pub metadata:ManuallyDrop<Option<ActionMeta>>,actor_source:Option<(usize,usize)>,offset:usize,phase:u8,retirement:RetainedCloneClose,construction:OriginalConstructionAdmission}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"response metadata changed its actual instance, actor, caller or receiving recipient")}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
impl OriginalResponseActionSource{
 fn admit_selection(instance:u32,surface:Option<&str>,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let settled=built_with(cx,admission,output,construction(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{instance,binding,decoder,body,surface:surface.map(|surface|(surface.as_ptr()as usize,surface.len())),capture:ManuallyDrop::new(None),owned_view:ManuallyDrop::new(None),view:ManuallyDrop::new(None),lease:ManuallyDrop::new(None),allocation:Default::default(),actor:ManuallyDrop::new(None),metadata:ManuallyDrop::new(None),actor_source:None,offset:0,phase:0,retirement:Default::default(),construction:Default::default()}),receipt(d)))})?;Ok(adopted(settled,admission,output,|owner|&mut owner.construction))}
 pub fn shared_admission(&mut self)->&mut semio_framework_value::native_decoding::NativeSharedAdmission<semio_framework::ViewModel>{&mut self.allocation}
 pub fn admit(instance:u32,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{Self::admit_selection(instance,None,cx,admission,output)}
 /// 🎯️ The selected original surface text remains borrowed from its retained intent throughout capture and handback.
 pub fn admit_surface(instance:u32,surface:&str,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{Self::admit_selection(instance,Some(surface),cx,admission,output)}
 fn validate_surface(&self,surface:Option<&str>)->Result<(),OriginalTurnFailure>{if self.surface!=surface.map(|surface|(surface.as_ptr()as usize,surface.len())){return Err(invalid().into())}Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn advance_cache(&mut self,surface:Option<&str>,registry:&mut semio_plugin_plugin_program::surface_context::SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.validate_surface(surface)?;match self.phase{0=>{if self.capture.is_none(){OriginalSurfaceViewCapture::admit(cx,&mut self.construction,&mut self.capture)?;return Ok(false)}if match surface{Some(surface)=>self.capture.as_mut().unwrap().advance_surface(registry,surface,cx)?,None=>self.capture.as_mut().unwrap().advance(registry,cx)?}{self.phase=1}},1=>{if self.capture.as_mut().unwrap().take_into(&mut self.owned_view,cx)?{self.phase=6}},_=>{}}Ok(self.phase>=2)}
 fn advance_actor(&mut self,text:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;match self.phase{
  6=>{if ActionMeta::admit_view_root(&mut self.owned_view,&mut self.view,&mut self.allocation,cx)?{self.phase=2}},
  2=>{let d=RetirementDemand{capacity_bytes:text.len(),..header::<String>()};let source=(text.as_ptr()as usize,text.len());let mut done=None;built(cx,&mut self.construction,&mut done,construction(d),||{*self.actor=Some(String::with_capacity(text.len()));self.actor_source=Some(source);self.phase=3;Ok(((),receipt(d)))})?;},
  3=>{if self.actor_source!=Some((text.as_ptr()as usize,text.len())){return Err(invalid().into())}let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}let d=RetirementDemand{copy_bytes:end-self.offset+size_of::<usize>()+size_of::<u8>(),depth:1,..Default::default()};let mut done=None;built(cx,&mut self.construction,&mut done,construction(d),||{self.actor.as_mut().unwrap().push_str(&text[self.offset..end]);self.offset=end;if end==text.len(){self.phase=4}Ok(((),receipt(d)))})?;},
  4=>{let mut d=semio_framework_value::SharedUtf8::admission_demand();d.copy_bytes=2*size_of::<ActionMeta>()+size_of::<String>();let g=cx.retained_grant();let mut actual=None;if built(cx,&mut self.construction,&mut self.metadata,construction(d),||{let(actor,_)=semio_framework_value::SharedUtf8::admit(self.actor.take().unwrap(),g,&mut actual).result.unwrap_or_else(|_|unreachable!("funded original actor header"));Ok((ActionMeta{ expected_document_revision:None,actor,instance_id:self.instance,view_state:self.view.take()},receipt(d)))})?{self.phase=5}},5=>return Ok(true),_=>return Err(invalid().into())}Ok(self.phase==5)}
 async fn advance_selected<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,surface:Option<&str>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.validate_surface(surface)?;if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"response metadata capture cancelled").into())}if self.phase<2{return with_instances_turn_mut(runtime,|list|{let mut instance=find_instance(list,self.instance)?;self.advance_cache(surface,&mut instance.surface_contexts,cx).map(|_|false)}).await}let actors=runtime.instance_actors.try_borrow().map_err(|_|invalid())?;let actor=actors.get(self.instance).ok_or_else(invalid)?;let text=std::str::from_utf8(&actor.bytes[..usize::from(actor.len)]).map_err(|_|invalid())?;self.advance_actor(text,cx)}
 pub fn ready(&self)->bool{self.phase==5}
 pub async fn advance<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,None,cx).await}
 pub async fn advance_surface<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,surface:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,Some(surface),cx).await}
 pub async fn close_step<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if let Some(capture)=self.capture.as_mut(){if !capture.terminal_is_empty(){with_instances_turn_mut(runtime,|list|{let mut instance=find_instance(list,self.instance)?;capture.close_step(&mut instance.surface_contexts,cx)}).await?;return Ok(false)}let d=OriginalSurfaceViewCapture::release_demand();retired(cx,d,|_|{self.capture.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;return Ok(false)}self.close_owned(cx)}
 /// 📏️ The selected original registry and retained body determine the next physical close action.
 pub fn close_demands(&self,registry:&semio_plugin_plugin_program::surface_context::SurfaceContexts)->Result<RetirementDemand,ValueError>{if !self.allocation.terminal_is_empty(){return self.allocation.close_demand()}if let Some(capture)=self.capture.as_ref(){return if capture.terminal_is_empty(){Ok(OriginalSurfaceViewCapture::release_demand())}else{capture.close_demands(registry)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)}if self.owned_view.is_some(){return self.retirement.next_owner_demands::<semio_framework::ViewModel>(true,&None,self.body)}if self.view.is_some()||self.lease.is_some(){return self.retirement.next_owner_demands::<ViewLease>(true,&None,self.body)}if self.actor.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,self.body)}Ok(Default::default())}
 fn close_owned(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.allocation.phase()!=semio_framework_value::native_decoding::NativeReceivingEffectPhase::Empty{return Err(invalid().into())}if self.allocation.has_birth(){let d=self.allocation.close_demand()?;retired_poll(cx,d,|effect|self.allocation.close_step(effect))?;return Ok(false)}if !self.retirement.is_empty(){let d=self.retirement.demands(self.body)?;retired_poll(cx,d,|effect|self.retirement.step_granted(self.body,effect))?;return Ok(false)}macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,self.body)?;begun(cx,d,|effect|self.retirement.begin_granted(&mut self.$field,effect))?;return Ok(false)}}}close!(metadata,ActionMeta);close!(owned_view,semio_framework::ViewModel);if let Some(view)=self.view.take(){*self.lease=Some(ViewLease::new(view))}close!(lease,ViewLease);close!(actor,String);unbuilt(cx,&mut self.construction)}
  pub fn terminal_is_empty(&self)->bool{self.allocation.terminal_is_empty()&&self.capture.is_none()&&self.owned_view.is_none()&&self.view.is_none()&&self.lease.is_none()&&self.actor.is_none()&&self.metadata.is_none()&&self.retirement.is_empty()&&self.construction.terminal_is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalResponseActionSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"response metadata source requires original physical closure")}}

